(function(){function textoHoraLocal(iso){if(!iso)return"";var d=new Date(iso);return isNaN(d.getTime())?"":d.toLocaleString(undefined,{dateStyle:"short",timeStyle:"short"})}document.querySelectorAll("[data-fecha-utc]").forEach(function(el){var t=textoHoraLocal(el.getAttribute("data-fecha-utc"));t&&(el.classList.contains("historial-fecha-en-titulo")?el.setAttribute("title","Última descarga: "+t):el.classList.contains("historial-fecha-en-celda")&&(el.textContent=t))})})();